}
.footer-brand p { font-size: 14px; max-width: 320px; margin: 14px 0 24px; color: var(--text-dim); }
.footer-brand .socials { display: flex; gap: 8px; }
.footer-brand .socials a {
  width: 38px; height: 38px;
  border: 1px solid var(--border);
  border-radius: 10px;
  display: grid; place-items: center;
  color: var(--text-dim);
  transition: color .2s, border-color .2s;
}
.footer-brand .socials a:hover { color: var(--text); border-color: var(--text-faint); }
.footer-col h4 {
  font-size: 12px;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--text);
  margin: 0 0 18px;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 12px; }
.footer-col a { font-size: 14px; color: var(--text-dim); transition: color .2s; }
.footer-col a:hover { color: var(--text); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  color: var(--text-faint);
  flex-wrap: wrap;
  gap: 12px;
