arguments.file_text:
:root {
  --bg: #0a0a0c;
  --bg-elev: #131318;
  --bg-elev-2: #1a1a22;
  --border: #26262f;
  --border-strong: #34343f;
  --text: #f2f2f5;
  --text-dim: #a4a4b0;
  --text-faint: #6a6a78;
  --accent: #d4ff3a;
  --accent-2: #ff5b6e;
  --accent-3: #7c5cff;
  --gold: #e8c87a;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow: 0 18px 48px rgba(0,0,0,.45);
  --max: 1320px;
  --font: "Inter", "Segoe UI", system-ui, -apple-system, sans-serif;
  --serif: "Fraunces", "Playfair Display", Georgia, serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  font-size: 15px;
  line-height: 1.55;
  overflow-x: hidden;
}
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; }
img { display: block; max-width: 100%; }

.container { max-width: var(--max); margin: 0 auto; padding: 0 28px; }

/* ---------- Announcement Bar ---------- */
.announce {
  background: linear-gradient(90deg, #1a1a22 0%, #131318 100%);
  border-bottom: 1px solid var(--border);
  font-size: 12px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--text-dim);
}
.announce-track {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 36px;
  padding: 10px 28px;
  overflow: hidden;
  white-space: nowrap;
}
.announce-track span { display: inline-flex; align-items: center; gap: 8px; }
.announce-track .dot { width: 4px; height: 4px; background: var(--accent); border-radius: 50%; }

/* ---------- Header ---------- */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10,10,12,.82);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  gap: 40px;
}
.logo {
  font-family: var(--serif);
  font-size: 24px;
  font-weight: 600;
  letter-spacing: -.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo-mark {
  width: 28px; height: 28px;
  background: var(--accent);
  color: #0a0a0c;
  border-radius: 8px;
  display: grid; place-items: center;
  font-family: var(--font);
  font-weight: 800;
  font-size: 14px;
}
.nav { display: flex; gap: 28px; }
.nav a {
  font-size: 14px;
  color: var(--text-dim);
  position: relative;
  padding: 6px 0;
  transition: color .2s;
}
.nav a:hover { color: var(--text); }
.nav a.active { color: var(--text); }
.nav a.active::after {
  content: "";
  position: absolute; left: 0; right: 0; bottom: -2px;
  height: 2px; background: var(--accent); border-radius: 2px;
}
.header-actions { display: flex; align-items: center; gap: 6px; }
.icon-btn {
  width: 40px; height: 40px;
  border-radius: 10px;
  background: transparent;
  color: var(--text-dim);
  display: grid; place-items: center;
  position: relative;
  transition: background .2s, color .2s;
}
.icon-btn:hover { background: var(--bg-elev); color: var(--text); }
.icon-btn .badge {
  position: absolute;
  top: 6px; right: 6px;
  background: var(--accent-2);
  color: white;
  font-size: 10px;
  font-weight: 700;
  min-width: 16px; height: 16px;
  border-radius: 8px;
  padding: 0 4px;
  display: grid; place-items: center;
  border: 2px solid var(--bg);
}
.search-wrap {
  flex: 1;
  max-width: 360px;
  position: relative;
}
.search-wrap input {
  width: 100%;
  height: 40px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 10px;
  padding: 0 12px 0 38px;
  font-size: 14px;
  outline: none;
  transition: border-color .2s, background .2s;
}
.search-wrap input:focus { border-color: var(--border-strong); background: var(--bg-elev-2); }
.search-wrap input::placeholder { color: var(--text-faint); }
.search-wrap svg {
  position: absolute;
  left: 12px; top: 50%;
  transform: translateY(-50%);
  color: var(--text-faint);
}

/* ---------- Hero ---------- */
.hero {
  position: relative;
  padding: 72px 0 88px;
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  top: -200px; right: -180px;
  width: 700px; height: 700px;
  background: radial-gradient(circle, rgba(124,92,255,.2) 0%, transparent 60%);
  pointer-events: none;
}
.hero::after {
  content: "";
  position: absolute;
  bottom: -200px; left: -180px;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(212,255,58,.08) 0%, transparent 60%);
  pointer-events: none;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 56px;
  align-items: center;
  position: relative;
  z-index: 1;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 999px;
  font-size: 12px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--text-dim);
}
.eyebrow .pulse {
  width: 6px; height: 6px;
  background: var(--accent); border-radius: 50%;
  box-shadow: 0 0 0 0 rgba(212,255,58,.6);
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(212,255,58,.6); }
  70% { box-shadow: 0 0 0 8px rgba(212,255,58,0); }
  100% { box-shadow: 0 0 0 0 rgba(212,255,58,0); }
}
.hero h1 {
  font-family: var(--serif);
  font-size: clamp(44px, 5.6vw, 76px);
  line-height: 1.02;
  font-weight: 500;
  letter-spacing: -.025em;
  margin: 22px 0 20px;
}
.hero h1 em {
  font-style: italic;
  color: var(--accent);
  font-weight: 400;
}
.hero p.lead {
  color: var(--text-dim);
  font-size: 17px;
  max-width: 480px;
  margin: 0 0 36px;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }
.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 22px;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -.01em;
  transition: transform .15s ease, background .2s, color .2s;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: #0a0a0c;
}
.btn-primary:hover { background: #c0eb22; }
.btn-ghost {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border-strong);
}
.btn-ghost:hover { background: var(--bg-elev); border-color: var(--text-faint); }
.hero-stats {
  display: flex;
  gap: 36px;
  margin-top: 56px;
  padding-top: 28px;
  border-top: 1px solid var(--border);
}
.hero-stats .stat strong {
  font-family: var(--serif);
  display: block;
  font-size: 32px;
  font-weight: 500;
  letter-spacing: -.02em;
}
.hero-stats .stat span {
  font-size: 12px;
  color: var(--text-faint);
  letter-spacing: .1em;
  text-transform: uppercase;
}

/* Hero visual */
.hero-visual {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: 24px;
  overflow: hidden;
  background:
    radial-gradient(circle at 30% 20%, rgba(124,92,255,.35), transparent 55%),
    radial-gradient(circle at 80% 80%, rgba(255,91,110,.25), transparent 55%),
    linear-gradient(160deg, #1a1a22 0%, #0d0d12 100%);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}
.hero-visual .hero-img {
  position: absolute;
  inset: 0;
  background-image: url("https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=1200&q=80");
  background-size: cover;
  background-position: center;
  filter: contrast(1.05) saturate(1.1) brightness(.92);
  mix-blend-mode: luminosity;
  opacity: .85;
}
.hero-visual::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(10,10,12,.7) 100%);
}
.hero-card {
  position: absolute;
  bottom: 24px; left: 24px; right: 24px;
  background: rgba(20,20,26,.72);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 14px;
  padding: 18px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  z-index: 2;
}
.hero-card .meta { font-size: 11px; letter-spacing: .14em; text-transform: uppercase; color: var(--text-faint); margin-bottom: 4px; }
.hero-card .title { font-family: var(--serif); font-size: 18px; font-weight: 500; }
.hero-card .price { font-weight: 600; }
.hero-card .price small { color: var(--text-faint); text-decoration: line-through; font-weight: 400; margin-right: 6px; }
.hero-card .cart {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: var(--accent);
  color: #0a0a0c;
  display: grid; place-items: center;
  flex-shrink: 0;
}
.floating-tag {
  position: absolute;
  top: 24px; right: 24px;
  background: var(--accent);
  color: #0a0a0c;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  padding: 8px 14px;
  border-radius: 999px;
  z-index: 2;
}

/* ---------- Section ---------- */
.section { padding: 72px 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 36px;
}
.section-head .label {
  font-size: 12px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 12px;
}
.section-head h2 {
  font-family: var(--serif);
  font-size: clamp(32px, 3.4vw, 46px);
  font-weight: 500;
  letter-spacing: -.02em;
  margin: 0;
  line-height: 1.05;
}
.section-head .desc { color: var(--text-dim); max-width: 420px; margin-top: 12px; }
.section-head .link {
  color: var(--text-dim);
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  padding-bottom: 8px;
  transition: color .2s;
}
.section-head .link:hover { color: var(--accent); }

/* ---------- Category Pills ---------- */
.cat-pills {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 28px;
}
.cat-pills button {
  padding: 9px 16px;
  border-radius: 999px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-dim);
  font-size: 13px;
  font-weight: 500;
  transition: all .2s;
}
.cat-pills button:hover { color: var(--text); border-color: var(--border-strong); }
.cat-pills button.active {
  background: var(--text);
  color: var(--bg);
  border-color: var(--text);
}

/* ---------- Product Grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
.product {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .25s ease, border-color .25s ease;
  position: relative;
  display: flex;
  flex-direction: column;
}
.product:hover { transform: translateY(-3px); border-color: var(--border-strong); }
.product .media {
  position: relative;
  aspect-ratio: 1/1;
  overflow: hidden;
  background: linear-gradient(135deg, #1f1f28 0%, #14141a 100%);
}
.product .media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.product:hover .media img { transform: scale(1.05); }
.product .tags {
  position: absolute;
  top: 12px; left: 12px;
  display: flex;
  gap: 6px;
}
.tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 6px;
  background: rgba(10,10,12,.72);
  backdrop-filter: blur(8px);
  color: var(--text);
}
.tag.new { background: var(--accent); color: #0a0a0c; }
.tag.sale { background: var(--accent-2); color: #fff; }
.tag.limited { background: var(--gold); color: #2a1f08; }
.product .fav {
  position: absolute;
  top: 12px; right: 12px;
  width: 36px; height: 36px;
  background: rgba(10,10,12,.72);
  backdrop-filter: blur(8px);
  border-radius: 50%;
  display: grid; place-items: center;
  color: var(--text-dim);
  border: none;
  transition: color .2s, background .2s;
}
.product .fav:hover, .product .fav.active { color: var(--accent-2); }
.product .fav.active svg { fill: var(--accent-2); }
.product .quick-add {
  position: absolute;
  left: 12px; right: 12px; bottom: 12px;
  height: 42px;
  background: var(--text);
  color: var(--bg);
  border-radius: 10px;
  font-weight: 600;
  font-size: 13px;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .25s ease, transform .25s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.product:hover .quick-add { opacity: 1; transform: translateY(0); }
.product .info {
  padding: 16px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.product .brand { font-size: 11px; letter-spacing: .14em; text-transform: uppercase; color: var(--text-faint); }
.product .name { font-size: 15px; font-weight: 500; color: var(--text); }
.product .row { display: flex; align-items: center; justify-content: space-between; margin-top: 6px; }
.product .price-now { font-weight: 600; font-size: 16px; }
.product .price-was { color: var(--text-faint); text-decoration: line-through; font-size: 13px; margin-left: 8px; font-weight: 400; }
.product .rating { display: inline-flex; align-items: center; gap: 4px; color: var(--text-dim); font-size: 12px; }
.product .rating svg { color: var(--gold); }

/* ---------- Deals Section ---------- */
.deals {
  background: linear-gradient(180deg, var(--bg) 0%, #0d0d12 100%);
  position: relative;
}
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 22px;
  min-height: 580px;
}
.deal {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border);
  padding: 32px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 280px;
  transition: transform .25s ease, border-color .25s ease;
  isolation: isolate;
}
.deal:hover { transform: translateY(-3px); border-color: var(--border-strong); }
.deal::before {
  content: "";
  position: absolute; inset: 0;
  z-index: -1;
  background-size: cover;
  background-position: center;
  transition: transform .6s ease;
}
.deal:hover::before { transform: scale(1.04); }
.deal::after {
  content: "";
  position: absolute; inset: 0;
  z-index: -1;
  background: linear-gradient(180deg, rgba(10,10,12,.4) 0%, rgba(10,10,12,.85) 100%);
}
.deal-1 { grid-row: 1 / span 2; min-height: 580px; }
.deal-1::before { background-image: url("https://images.unsplash.com/photo-1489987707025-afc232f7ea0f?w=900&q=80"); }
.deal-2::before { background-image: url("https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=600&q=80"); }
.deal-3::before { background-image: url("https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=600&q=80"); }
.deal-4::before { background-image: url("https://images.unsplash.com/photo-1515955656352-a1fa3ffcd111?w=600&q=80"); }
.deal-5::before { background-image: url("https://images.unsplash.com/photo-1591047139829-d91aecb6caea?w=600&q=80"); }

.deal .deal-tag {
  align-self: flex-start;
  background: var(--accent);
  color: #0a0a0c;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  padding: 6px 12px;
  border-radius: 6px;
}
.deal .deal-tag.red { background: var(--accent-2); color: white; }
.deal .deal-tag.purple { background: var(--accent-3); color: white; }
.deal h3 {
  font-family: var(--serif);
  font-size: 28px;
  font-weight: 500;
  letter-spacing: -.02em;
  margin: 0 0 6px;
  line-height: 1.1;
}
.deal-1 h3 { font-size: 44px; }
.deal p { color: var(--text-dim); font-size: 14px; margin: 0 0 16px; max-width: 320px; }
.deal .deal-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  padding: 10px 0;
  position: relative;
  width: fit-content;
}
.deal .deal-link::after {
  content: "";
  position: absolute; left: 0; bottom: 6px;
  width: 100%; height: 1px;
  background: var(--text);
  transform-origin: left;
  transition: transform .3s;
}
.deal:hover .deal-link::after { transform: scaleX(1.1); }

/* Countdown */
.countdown {
  display: flex;
  gap: 10px;
  margin-top: 16px;
}
.countdown .unit {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.1);
  backdrop-filter: blur(8px);
  border-radius: 8px;
  padding: 8px 12px;
  text-align: center;
  min-width: 56px;
}
.countdown .unit strong {
  display: block;
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
.countdown .unit span {
  font-size: 10px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--text-dim);
}

/* ---------- Editorial ---------- */
.editorial {
  border-top: 1px solid var(--border);
  background: #0c0c10;
}
.editorial-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 24px;
}
.article {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .25s ease, border-color .25s ease;
}
.article:hover { transform: translateY(-3px); border-color: var(--border-strong); }
.article .cover {
  aspect-ratio: 16/10;
  background-size: cover;
  background-position: center;
  position: relative;
  overflow: hidden;
}
.article.feat .cover { aspect-ratio: 4/5; }
.article .cover::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(10,10,12,.6) 100%);
}
.article .cat {
  position: absolute;
  top: 16px; left: 16px;
  font-size: 11px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--text);
  background: rgba(10,10,12,.6);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255,255,255,.1);
  padding: 6px 10px;
  border-radius: 6px;
  z-index: 2;
}
.article .body { padding: 22px 24px 24px; flex: 1; display: flex; flex-direction: column; }
.article.feat .body { padding: 28px 30px 30px; }
.article .meta {
  font-size: 12px;
  color: var(--text-faint);
  letter-spacing: .08em;
  text-transform: uppercase;
  margin-bottom: 10px;
}
.article h3 {
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: -.015em;
  font-size: 22px;
  margin: 0 0 10px;
  line-height: 1.2;
}
.article.feat h3 { font-size: 32px; }
.article .excerpt { color: var(--text-dim); font-size: 14px; margin: 0 0 18px; }
.article .read {
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: auto;
}

/* ---------- Brand strip ---------- */
.brand-strip {
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 32px 0;
  background: #0b0b0f;
}
.brand-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 36px;
  flex-wrap: wrap;
}
.brand-row .b {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 500;
  letter-spacing: -.02em;
  color: var(--text-faint);
  opacity: .7;
  transition: opacity .2s, color .2s;
}
.brand-row .b:hover { opacity: 1; color: var(--text); }
.brand-row .b.italic { font-style: italic; }
.brand-row .b.upper { text-transform: uppercase; letter-spacing: .2em; font-family: var(--font); font-size: 14px; font-weight: 700; }

/* ---------- Newsletter ---------- */
.newsletter {
  position: relative;
  padding: 96px 0;
  overflow: hidden;
}
.newsletter::before {
  content: "";
  position: absolute;
  top: 50%; left: 50%;
  width: 900px; height: 900px;
  background: radial-gradient(circle, rgba(124,92,255,.18) 0%, transparent 60%);
  transform: translate(-50%,-50%);
  pointer-events: none;
}
.newsletter-card {
  position: relative;
  background: linear-gradient(160deg, var(--bg-elev-2) 0%, var(--bg-elev) 100%);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 64px;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 56px;
  align-items: center;
  overflow: hidden;
}
.newsletter-card::before {
  content: "";
  position: absolute;
  top: -150px; right: -100px;
  width: 380px; height: 380px;
  background: radial-gradient(circle, rgba(212,255,58,.18) 0%, transparent 65%);
}
.newsletter h2 {
  font-family: var(--serif);
  font-size: clamp(32px, 3.4vw, 44px);
  font-weight: 500;
  letter-spacing: -.02em;
  line-height: 1.05;
  margin: 12px 0 16px;
}
.newsletter p { color: var(--text-dim); margin: 0; max-width: 420px; }
.newsletter form {
  display: flex;
  gap: 8px;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  padding: 6px;
}
.newsletter form input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text);
  padding: 0 16px;
  font-size: 15px;
  outline: none;
  font-family: inherit;
}
.newsletter form input::placeholder { color: var(--text-faint); }
.newsletter form button {
  background: var(--accent);
  color: #0a0a0c;
  padding: 14px 24px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 14px;
  white-space: nowrap;
  transition: background .2s;
}
.newsletter form button:hover { background: #c0eb22; }
.newsletter .perks {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.newsletter .perk {
  display: flex; align-items: flex-start; gap: 14px;
}
.newsletter .perk .ic {
  width: 40px; height: 40px;
  background: rgba(212,255,58,.12);
  border: 1px solid rgba(212,255,58,.2);
  border-radius: 10px;
  display: grid; place-items: center;
  color: var(--accent);
  flex-shrink: 0;
}
.newsletter .perk strong { display: block; font-size: 14px; font-weight: 600; margin-bottom: 2px; }
.newsletter .perk span { font-size: 13px; color: var(--text-dim); }

/* ---------- Footer ---------- */
.footer {
  background: #08080b;
  border-top: 1px solid var(--border);
  padding: 72px 0 28px;
  color: var(--text-dim);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 56px;
  margin-bottom: 56px;
}
.footer-brand p { font-size: 14px; max-width: 320px; margin: 14px 0 24px; color: var(--text-dim); }
.footer-brand .socials { display: flex; gap: 8px; }
.footer-brand .socials a {
  width: 38px; height: 38px;
  border: 1px solid var(--border);
  border-radius: 10px;
  display: grid; place-items: center;
  color: var(--text-dim);
  transition: color .2s, border-color .2s;
}
.footer-brand .socials a:hover { color: var(--text); border-color: var(--text-faint); }
.footer-col h4 {
  font-size: 12px;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--text);
  margin: 0 0 18px;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 12px; }
.footer-col a { font-size: 14px; color: var(--text-dim); transition: color .2s; }
.footer-col a:hover { color: var(--text); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  color: var(--text-faint);
  flex-wrap: wrap;
  gap: 12px;
}
.footer-bottom .legal { display: flex; gap: 22px; }

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  bottom: 28px; right: 28px;
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 14px 18px;
  border-radius: 12px;
  font-size: 14px;
  display: flex; align-items: center; gap: 12px;
  box-shadow: var(--shadow);
  transform: translateY(140%);
  transition: transform .3s ease;
  z-index: 1000;
}
.toast.show { transform: translateY(0); }
.toast .check { width: 22px; height: 22px; background: var(--accent); color: #0a0a0c; border-radius: 50%; display: grid; place-items: center; }

/* ---------- Responsive ---------- */
@media (max-width: 1100px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto auto auto; }
  .deal-1 { grid-row: 1 / span 1; min-height: 320px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .article.feat { grid-column: 1 / -1; }
  .article.feat .cover { aspect-ratio: 21/9; }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 820px) {
  .nav { display: none; }
  .search-wrap { display: none; }
  .hero { padding: 48px 0 56px; }
  .hero-grid { grid-template-columns: 1fr; gap: 36px; }
  .hero-stats { gap: 20px; }
  .hero-stats .stat strong { font-size: 26px; }
  .product-grid { grid-template-columns: 1fr 1fr; gap: 14px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-1, .deal { min-height: 260px; }
  .deal-1 h3 { font-size: 32px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .newsletter-card { grid-template-columns: 1fr; padding: 36px 28px; gap: 32px; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 36px; }
  .section { padding: 56px 0; }
}
@media (max-width: 480px) {
  .container { padding: 0 18px; }
  .product-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

