const Countdown = () => {
  const [t, setT] = useState({ d: 2, h: 14, m: 33, s: 12 });
  useEffect(() => {
    const id = setInterval(() => {
      setT(prev => {
        let { d, h, m, s } = prev;
        s--;
        if (s < 0) { s = 59; m--; }
        if (m < 0) { m = 59; h--; }
        if (h < 0) { h = 23; d--; }
        if (d < 0) { d = 0; h = 0; m = 0; s = 0; }
        return { d, h, m, s };
      });
    }, 1000);
    return () => clearInterval(id);
  }, []);
  const pad = n => String(n).padStart(2, "0");
  return h("div", { className: "countdown" },
    h("div", { className: "unit" }, h("strong", null, pad(t.d)), h("span", null, "Days")),
    h("div", { className: "unit" }, h("strong", null, pad(t.h)), h("span", null, "Hrs")),
    h("div", { className: "unit" }, h("strong", null, pad(t.m)), h("span", null, "Min")),
    h("div", { className: "unit" }, h("strong", null, pad(t.s)), h("span", null, "Sec"))
  );
};

