/* ---------------- App ---------------- */
const App = () => {
  const [cart, setCart] = useState(0);
  const [favs, setFavs] = useState([1, 4]);
  const [toast, setToast] = useState({ show: false, msg: "" });

  const showToast = useCallback((msg) => {
    setToast({ show: true, msg });
    clearTimeout(window.__t);
    window.__t = setTimeout(() => setToast(s => ({ ...s, show: false })), 2400);
  }, []);

  const handleAdd = useCallback((name) => {
    setCart(c => c + 1);
    showToast(`Added "${name}" to your bag`);
  }, [showToast]);

  const handleFav = useCallback((id) => {
    setFavs(f => {
      const next = f.includes(id) ? f.filter(x => x !== id) : [...f, id];
      showToast(f.includes(id) ? "Removed from wishlist" : "Saved to wishlist");
      return next;
    });
  }, [showToast]);

  const handleSubscribe = useCallback((email) => {
    showToast(`Welcome — confirmation sent to ${email}`);
  }, [showToast]);

  return h(Fragment, null,
    h(Announce),
    h(Header, { cartCount: cart, favCount: favs.length }),
    h("main", null,
      h(Hero, { onAdd: handleAdd }),
      h(Featured, { onAdd: handleAdd, favs, onFav: handleFav }),
      h(Deals),
      h(Editorial),
      h(BrandStrip),
      h(Newsletter, { onSubscribe: handleSubscribe })
    ),
    h(Footer),
    h(Toast, { message: toast.msg, show: toast.show })
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(h(App));
